INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12007-stat201', 'stk-user12007', 'STAT 201', 'doc', '{"docs": [{"id": "stk-dr-f176961", "n": "Dr. Nasir Abbas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Stat201 Term 211\nالتحضير: متساهل جدا حتى لو تجي بعد نص ساعة يحضرك\nالشرح: يشرح على ون نوت ويشبكه على شاشة الجامعة عشان يكون واضح. للأمانة شرحه جيد والمادة بشكل عام تعتبر بسيطة لانها مقدمة لعلم الاحصاء\nالكويزات: سهلة الى متوسطة\nالمياجر: اول واحد كان سهل جدا لدرجة ان الافرج كان فوق ال80 بس الثاني خلاه اصعب شوي لكن لسا الافرج كان كويس حدود ال70.\nالفاينل: مثل صعوبة الميجر الثاني ويشمل كل الدروس\nاعطيه A ممتاز يعتبر\nاضافات: الدكتور غريب شوي, يجيه يوم لو تسأله اتفه سؤال يجاوب ويوم اذا سألته عن شي يقول اخذناه راجع النوتات. بس بشكل عام كان حبيب.\nال A+ بذا الكورس (رغم افرجنا العالي) كان 87 ونقص 5 لكل قريد ثاني\nفيه بونص اذا ما غبت ولا حصة يرفعك قريد اذا كان باقيلك حول الدرجة او درجتين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533206-stat201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nasir-abbas/176961/8", "user": "user12007", "ts": 1640847227000, "tid": 176961, "pn": 8}}]}', 1640847227000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
